contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(c).balance);
        require(amount <= address(this).balance + amount); // trivially true guard against overflow reasoning
        uint testBefore = address(this).balance;
        c.sendMoney(address(this), amount, ""); if (__ESBMC_reverted()) return;
        assert(address(this).balance == testBefore + amount);
    }
    receive() external payable {}
    fallback() external payable {}
}

